            let i = parseInt(n.Id);
            n.HavePicture && this.imageId > i ? this.imageId = i : !n.HavePicture && this.textId > i && (this.textId = i);
            t += `<div class="item col-md-4 col-xs-12 bg-${n.HavePicture}" data-id="${n.Id}"><div>`;
            t += n.HavePicture ? `<div class="img-section"><img src="https://cdn.idero.ir/file/public/${n.Hash[0]}/${n.Hash}.jpg" alt="Alternate Text" class="ico-image" /><span class="nick">@${n.Name}</span></div>` : `<span class="nt-nick">@${n.Name}</span>`;
            t += `<h2>${n.Title}</h2><content>${n.Content}</content><div class="rate-star" style="background-image:url('/Content/Images/icon/star${n.Rate}.png')"></div></div></div>`
