class storePriceGenerator {
    constructor(n, t) {
        this.priceList = JSON.parse(n);
        this.branchList = JSON.parse(t);
        this.branchInitialize();
        this.colorChange()
    }

    branchInitialize() {
        $("#branchId").val(this.branchList[0].id);
        this.branchList.length > 1 ? ($("#branchDiv").show(), this.branchList.forEach(n => {
            $("#branchDiv select").append(`<option value="${n.id}">${n.title}</option>`)
        }), this.branchChange()) : this.priceChange()
    }

    branchChange() {
        let n = this;
        $("#branchDiv select").change(function () {
            let i = $(this);
            $("#branchId").val(i.val());
            let t = n.branchList.find(n => n.id == i.val());
            $('[data-pr="w"] i').html(t.ow + " cm");
            $('[data-pr="w"]').data("parameter", t.ow);
            $('[data-pr="h"] i').html(t.oh + " cm");
            $('[data-pr="h"]').data("parameter", t.oh);
            $('[data-pr="l"] i').html(t.ol + " cm");
            $('[data-pr="l"]').data("parameter", t.ol);
            $('[data-pr="d"] i').html(t.od + " cm");
            $('[data-pr="d"]').data("parameter", t.od);
            n.priceChange()
        }).change()
    }

    priceChange() {
        let t = $("#colorId").val(), i = $("#branchId").val();
        this.clearMinus();
        for (var n = 0; n < this.priceList.length; n++) {
            let r = this.priceList[n];
            if (r.bid == i && r.mid == t) {
                $("#productBranchPriceId").val(r.id);
                $("#productPrice").html(priceSplit(r.p));
                return
            }
        }
        console.log("error on price change")
    }

    colorChange() {
        let n = this;
        $("#colorList button").click(function () {
            $("#colorName").html($(this).data("color-name"));
            $("#colorId").val($(this).data("color-id"));
            $("#colorList button").removeClass("active");
            $(this).addClass("active");
            n.priceChange()
        })
    }

    clearMinus = () => {
        $("[data-parameter]").each(function () {
            let n = $(this);
            if (n.data("parameter") == -1) n.hide(); else n.show()
        })
    };
}

