$("[data-slider]").each(function () {
    let n = $(this), t = $(this).data("slider") === "auto" ? !0 : !1;
    n.find("[data-left]").click(function () {
        var i = n.width(), t = n.find(".item").width() + 50, r = Math.floor(i / t) * t, u = n.scrollLeft();
        n.animate({scrollLeft: u - r}, 200)
    });
    n.find("[data-right]").click(function () {
        var i = n.width(), t = n.find(".item").width() + 50, r = Math.floor(i / t) * t, u = n.scrollLeft();
        n.animate({scrollLeft: u + r}, 200)
    })
});